INSERT INTO ANALYSE (ID_DOCUMENT, NUM_ANALYSE, PM, AM1, AM2, AM3, AM4, AM5, AM6, AM7, AM8, AM9, AM10, AM11, AM12, SOMMAIRE, TITRE_REFERENCE) VALUES (${SOURCEID}, 1, 'AUTORITE PARENTALE*', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Le parent qui n''a plus l''exercice de l''autorité parentale à la suite d''une délégation de celle-ci au service à qui l''enfant a été confié, est recevable à reprocher à la cour d''appel d''avoir omis de rechercher si les mineurs avaient été informés de leur droit à être entendus par le juge, ni de l''avoir mentionné dans l''arrêt, dès lors que la charge d''une telle information et la justification de son exécution ne lui incombaient pas', NULL);
INSERT INTO ANALYSE (ID_DOCUMENT, NUM_ANALYSE, PM, AM1, AM2, AM3, AM4, AM5, AM6, AM7, AM8, AM9, AM10, AM11, AM12, SOMMAIRE, TITRE_REFERENCE) VALUES (${SOURCEID}, 2, 'AUTORITE PARENTALE*', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Il résulte des articles 338-1, alinéa 1 et 5, du code de procédure civile que le mineur capable de discernement est informé par le ou les titulaires de l''exercice de l''autorité parentale, le tuteur ou, le cas échéant, par la personne ou le service à qui il a été confié de son droit à être entendu et à être assisté d''un avocat dans toutes les procédures le concernant, mention étant faite, dans toute décision relative à un mineur capable de discernement, qu''ils se sont acquittés de leur obligation.\n\nDoit être censuré l''arrêt qui prononce une délégation de l''exercice de l''autorité parentale à l''aide sociale à l''enfance sans qu''il ne résulte ni de ses mentions, ni des pièces de la procédure que le mineur ait été avisé par le service gardien de son droit à être entendu dans la procédure le concernant ou qu''il ait été considéré comme dépourvu de discernement', NULL);